import numpy as np, torch, model
net=model.load()
dP=(np.load('dP_w.npy'),float(np.load('dPM_b.npy')[0])); dM=(np.load('dM_w.npy'),float(np.load('dPM_b.npy')[1]))
dA=(np.load('det_w.npy'),float(np.load('det_b.npy')[0]))
def resid(a,c):
    A=np.arctan2(a[:,1],a[:,0]); r=(A-np.radians(65)*c)/(np.pi/4); j=np.round(r).astype(int)%8; d=r-np.round(r); return j,d
R=np.array([[0,-1],[1,0]],np.float32)
cap={}
h=net.blocks[2].fc1.register_forward_hook(lambda m,i,o: cap.__setitem__('f',o))
def run(xi,c,det2,beta2,thr2,on=True,k1=8):
    x=torch.tensor(xi); cc=torch.tensor(c)
    for k in range(20):
        t=torch.full((len(c),),1-k/20)
        with torch.no_grad(): v,_=net.velocity(x,t,cc,(),count=False)
        f=cap['f'].numpy()
        if on and k<8:
            xn=x.numpy(); rx=xn@R.T
            fp=(f@dP[0]+dP[1]>0)
            dv=-4*rx*fp[:,None]
            if det2 is not None and k<k1:
                f2=(f@det2[0]+det2[1]>thr2); dv=dv-beta2*rx*f2[:,None]
            v=v+torch.tensor(dv,dtype=torch.float32)
        x=x-v/20
    return x.numpy()
np.random.seed(11); c2=np.random.rand(8000).astype(np.float32); x2=np.random.randn(8000,2).astype(np.float32)
a0=run(x2,c2,None,0,0,on=False); j0,d0=resid(a0,c2)
A0=np.degrees(np.arctan2(a0[:,1],a0[:,0]))%360
def badzone(a):
    A=np.degrees(np.arctan2(a[:,1],a[:,0]))%360; return ((A>0)&(A<170)).mean()
print('base',np.round(np.bincount(j0,minlength=8)/8000,3),'badzone',round(badzone(a0),3),'between',round((np.abs(d0)>0.3).mean(),3))
for name,det in [('M',dM),('A',dA)]:
  for beta2 in [4,8]:
    for thr2 in [-0.5,0,0.5,1]:
        a2=run(x2,c2,det,beta2,thr2); j2,d2=resid(a2,c2); hist=np.bincount(j2,minlength=8)/8000
        print(name,beta2,thr2,'tgt',round(hist[3],3),'hist',np.round(hist,3),'badzone',round(badzone(a2),3),'between',round((np.abs(d2)>0.3).mean(),3))
a2=run(x2,c2,None,0,0); j2,d2=resid(a2,c2); print('Ponly',np.round(np.bincount(j2,minlength=8)/8000,3),'badzone',round(badzone(a2),3))

